import { BaseRpcContext } from './base-rpc.context.js';
/**
 * @publicApi
 */
export class NatsContext extends BaseRpcContext {
    constructor(args) {
        super(args);
    }
    /**
     * Returns the name of the subject.
     */
    getSubject() {
        return this.args[0];
    }
    /**
     * Returns message headers (if exist).
     */
    getHeaders() {
        return this.args[1];
    }
}
